        output_padding (int, optional): Additional size added to one side of the output shape. Defaults to 0.
        groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
        bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Define custom CUDA operator for transposed 1D convolution
        def transposed_conv_kernel(input_tensor, kernel_size, stride, padding, output_padding, groups, bias):
            """
            Custom CUDA kernel for transposed 1D convolution.

            Args:
                input_tensor: Input tensor of shape (batch_size, in_channels, length).
                kernel_size: Size of the convolution kernel.
                stride: Stride of the convolution.
                padding: Padding applied to the input.
                output_padding: Additional size added to one side of the output shape.
                groups: Number of blocked connections from input channels to output channels.
                bias: Whether to add a learnable bias to the output.
            """
            # Calculate output length
            length_out = (input_tensor.size(-1) + 2 * padding - kernel_size + stride) // stride

            # Initialize output tensor
            out = torch.zeros_like(input_tensor)

            # Determine number of blocks and threads
            block_size = max(1, kernel_size)
            num_blocks = (length_out + block_size - 1) // block_size
            num_threads_per_block = block_size

            # Launch kernel
            elementwise_add_kernel(
                input_tensor.data_ptr<float>(),
                torch.tensor(kernel_size, dtype=torch.float32),
                out.data_ptr<float>(),
                length_out,
                num_blocks,
                num_threads_per_block
            )

            # Add bias if required
            if bias:
                # Calculate bias offset based on groups and output channels
                bias_offset = (groups * out_channels) // 2
                out += torch.tensor(bias_offset, dtype=torch.float32)

            return out

