        elementwise_add_kernel = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void transposed_conv_kernel(const float* input, int kernel_size, int stride, int padding, int output_padding, int groups, bool bias) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < length_out) {
        // Calculate the position in the output tensor
        int out_idx = idx % (groups * out_channels);
        int channel_idx = (out_idx / groups) % out_channels;

        // Apply convolution operation
        for (int k = 0; k < kernel_size; k++) {
            if (k == 0 && bias) {
                out[idx] += bias;
            } else {
                int offset = (k * kernel_size + k) / stride;
                out[idx] += input[idx - offset];
            }
        }
    }
}

